## Why This Is Asked

This question evaluates the ability to design a low-latency, ordered broadcast path with backpressure and dynamic scaling for a high-traffic chat system—similar to workloads at Discord, Cloudflare, and data platforms.

## Key Concepts

- **Per-room ordering** via per-room sequence numbers or monotonically increasing room-level sequence IDs
- **Bounded queues** with backpressure signaling (e.g., pushback, drop policies)
- **Dynamic worker scaling** per room based on queue depth or throughput metrics
- **Event prioritization** and graceful degradation under load
- **Testing strategies** for concurrency, ordering guarantees, and failure scenarios

## Solution Overview

Use per-room sequence numbers and per-room FIFO buffers. Route events through a central bounded queue to a per-room dispatcher, then to pools of workers dedicated to each room. Maintain order by storing the global or room-level sequence number in each event and processing events in per-room priority queues ordered by this sequence number.

## Code Example

```go
package main

import (
	"context"
	"sync"
	"time"
)

type EventType int
const (
	EventTypeMessage EventType = iota
	EventTypeJoin
	EventTypeLeave
)

type Event struct {
	RoomID   string
	EventID  string
	Type     EventType
	Payload  string
	SeqNum   int64
}

type Room struct {
	ID           string
	mu           sync.RWMutex
	buffer       []Event
	capacity     int
	workers      int
	clients      map[chan<- Event]struct{}
	sequenceNum  int64
}

func NewRoom(id string, capacity int) *Room {
	return &Room{
		ID:       id,
		capacity: capacity,
		clients:  make(map[chan<- Event]struct{}),
	}
}

func (r *Room) PushEvent(e Event) bool {
	r.mu.Lock()
	defer r.mu.Unlock()

	if len(r.buffer) >= r.capacity {
		return r.handleBackpressure(e)
	}

	r.buffer = append(r.buffer, e)
	return true
}

func (r *Room) handleBackpressure(e Event) bool {
	if e.Type == EventTypeJoin || e.Type == EventTypeLeave {
		r.buffer = append(r.buffer, e)
		if len(r.buffer) > r.capacity {
			r.buffer = r.buffer[1:]
		}
		return true
	}
	return false
}

func (r *Room) Broadcast(ctx context.Context) {
	ticker := time.NewTicker(10 * time.Millisecond)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			r.mu.RLock()
			if len(r.buffer) == 0 {
				r.mu.RUnlock()
				continue
			}
			event := r.buffer[0]
			r.buffer = r.buffer[1:]
			clients := make([]chan<- Event, 0, len(r.clients))
			for ch := range r.clients {
				clients = append(clients, ch)
			}
			r.mu.RUnlock()

			for _, ch := range clients {
				select {
				case ch <- event:
				default:
				}
			}
		}
	}
}

type Distributor struct {
	mu      sync.RWMutex
	rooms   map[string]*Room
	input   chan Event
	wg      sync.WaitGroup
	ctx     context.Context
	cancel  context.CancelFunc
}

func NewDistributor(bufferPerRoom int) *Distributor {
	ctx, cancel := context.WithCancel(context.Background())
	return &Distributor{
		rooms:  make(map[string]*Room),
		input:  make(chan Event, 10000),
		ctx:    ctx,
		cancel: cancel,
	}
}

func (d *Distributor) GetRoom(roomID string) *Room {
	d.mu.Lock()
	defer d.mu.Unlock()

	if room, ok := d.rooms[roomID]; ok {
		return room
	}

	room := NewRoom(roomID, 1000)
	d.rooms[roomID] = room
	d.wg.Add(1)
	go func() {
		defer d.wg.Done()
		room.Broadcast(d.ctx)
	}()
	return room
}

func (d *Distributor) Run() {
	for {
		select {
		case <-d.ctx.Done():
			return
		case event := <-d.input:
			room := d.GetRoom(event.RoomID)
			room.PushEvent(event)
		}
	}
}

func (d *Distributor) Publish(event Event) {
	select {
	case d.input <- event:
	default:
	}
}

func (d *Distributor) Shutdown() {
	d.cancel()
	close(d.input)
	d.wg.Wait()
}

func main() {
	d := NewDistributor(1000)
	go d.Run()

	d.Publish(Event{
		RoomID:  "room-1",
		EventID: "evt-1",
		Type:    EventTypeJoin,
		Payload: "user-1 joined",
	})

	time.Sleep(100 * time.Millisecond)
	d.Shutdown()
}
```

## Test Plan

1. **Ordering Tests**: Publish 1000 events per room out of order; verify they are delivered in sequence number order.
2. **Backpressure Tests**: Fill buffers to capacity; verify join/leave events are preserved while messages are dropped.
3. **Concurrency Tests**: Run 10 producers and 10 consumers per room simultaneously; check for race conditions and data races.
4. **Dynamic Scaling Tests**: Simulate burst traffic; verify worker count increases and decreases based on queue depth.
5. **Failure Recovery**: Kill rooms mid-broadcast; verify system continues operating and new rooms spawn correctly.
6. **Latency Tests**: Measure end-to-end latency under load; ensure p99 < 50ms for priority events.

## Why This Question Is Asked
This tests understanding of per-topic ordering, backpressure mechanisms, dynamic topic management, and safe shutdown in a concurrent dispatcher system.

## Key Concepts
- **Bounded backlog and backpressure**: Prevent memory exhaustion by limiting queue depth and signaling producers when buffers are full
- **Per-topic FIFO with ordering guarantees**: Ensure events within each topic maintain publication order
- **Fair scheduling (round-robin)**: Prevent a high-volume topic from starving others
- **Dynamic topic management**: Support on-the-fly topic creation as new device types appear
- **Cancellation and graceful shutdown**: Safely drain pending work without data loss

## Code Example
```go
package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

type Event struct {
	Topic   string
	Payload string
}

type TopicQueue struct {
	ch     chan Event
	mu     sync.Mutex
	closed bool
}

type Dispatcher struct {
	globalBacklog chan Event
	topicQueues  map[string]*TopicQueue
	workers      int
	wg           sync.WaitGroup
	mu           sync.RWMutex
	ctx          context.Context
	cancel       context.CancelFunc
}

func NewDispatcher(backlogSize, workers int) *Dispatcher {
	ctx, cancel := context.WithCancel(context.Background())
	d := &Dispatcher{
		globalBacklog: make(chan Event, backlogSize),
		topicQueues:  make(map[string]*TopicQueue),
		workers:      workers,
		ctx:          ctx,
		cancel:       cancel,
	}
	return d
}

func (d *Dispatcher) getOrCreateTopic(topic string) *TopicQueue {
	d.mu.Lock()
	defer d.mu.Unlock()
	if q, ok := d.topicQueues[topic]; ok {
		return q
	}
	q := &TopicQueue{ch: make(chan Event, 100)}
	d.topicQueues[topic] = q
	return q
}

func (d *Dispatcher) Enqueue(e Event) error {
	select {
	case d.globalBacklog <- e:
		return nil
	default:
		return fmt.Errorf("backpressure: global backlog full")
	}
}

func (d *Dispatcher) Start() {
	for i := 0; i < d.workers; i++ {
		d.wg.Add(1)
		go d.worker(i)
	}
	go d.dispatcher()
}

func (d *Dispatcher) dispatcher() {
	for {
		select {
		case <-d.ctx.Done():
			return
		case e := <-d.globalBacklog:
			q := d.getOrCreateTopic(e.Topic)
			select {
			case q.ch <- e:
			default:
				fmt.Printf("backpressure: topic %s full\n", e.Topic)
			}
		}
	}
}

func (d *Dispatcher) worker(id int) {
	defer d.wg.Done()
	for {
		select {
		case <-d.ctx.Done():
			return
		default:
		}
		d.mu.RLock()
		topics := make([]string, 0, len(d.topicQueues))
		for t := range d.topicQueues {
			topics = append(topics, t)
		}
		d.mu.RUnlock()
		if len(topics) == 0 {
			time.Sleep(time.Millisecond)
			continue
		}
		for _, topic := range topics {
			d.mu.RLock()
			q, ok := d.topicQueues[topic]
			d.mu.RUnlock()
			if !ok {
				continue
			}
			select {
			case e := <-q.ch:
				fmt.Printf("worker %d processed: %s -> %s\n", id, e.Topic, e.Payload)
			default:
			}
		}
	}
}

func (d *Dispatcher) Shutdown() {
	d.cancel()
	d.wg.Wait()
	d.mu.Lock()
	defer d.mu.Unlock()
	for _, q := range d.topicQueues {
		close(q.ch)
	}
}

func main() {
	d := NewDispatcher(1000, 3)
	d.Start()

	d.Enqueue(Event{Topic: "temperature", Payload: "25.5"})
	d.Enqueue(Event{Topic: "humidity", Payload: "60%"})
	d.Enqueue(Event{Topic: "temperature", Payload: "26.0"})

	time.Sleep(100 * time.Millisecond)
	d.Shutdown()
	fmt.Println("shutdown complete")
}
```

